// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }

    receive() external payable {}

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1000 ether);
        vm.deal(address(c), amount);
        bool ok;
        try c.withdraw() { ok = true; } catch { ok = false; }
        assertTrue(ok && address(c).balance == 0);
    }
}
